import{_t as e,it as t,n,rt as r}from"./chunks/framework.DaD4z1Q-.js";var i=JSON.parse(`{"title":"Troubleshooting prefixing problems","description":"Fix class not found errors, undefined constants and functions, stale source files and objects that stop matching between plugins after prefixing.","frontmatter":{"title":"Troubleshooting prefixing problems","description":"Fix class not found errors, undefined constants and functions, stale source files and objects that stop matching between plugins after prefixing."},"headers":[],"relativePath":"guide/common-problems.md","filePath":"guide/common-problems.md"}`),a={name:`guide/common-problems.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="common-problems" tabindex="-1">Common problems <a class="header-anchor" href="#common-problems" aria-label="Permalink to “Common problems”">​</a></h1><h2 id="class-vendor-not-found-very-early-in-a-request" tabindex="-1">Class &quot;…\\Vendor\\…&quot; not found, very early in a request <a class="header-anchor" href="#class-vendor-not-found-very-early-in-a-request" aria-label="Permalink to “Class &quot;…\\Vendor\\…&quot; not found, very early in a request”">​</a></h2><p>The prefixed autoloader has not been loaded yet when the code runs. This happens in code that runs before plugins, such as an <code>object-cache.php</code> drop-in or a firewall started from <code>wp-config.php</code>. Turn on <a href="./autoloader.html#loading-it"><code>include_autoloader</code></a> so anything that loads Composer&#39;s <code>vendor/autoload.php</code> gets the prefixed packages too, or require <code>vendor-prefixed/autoload.php</code> from that code.</p><h2 id="undefined-constant-such-as-acme-mb-case-title" tabindex="-1">Undefined constant such as <code>ACME_MB_CASE_TITLE</code> <a class="header-anchor" href="#undefined-constant-such-as-acme-mb-case-title" aria-label="Permalink to “Undefined constant such as ACME_MB_CASE_TITLE”">​</a></h2><p>A polyfill declares a constant that PHP already defines, and the polyfill&#39;s copy was renamed. Turn on the <a href="./exclusions.html#php-constants"><code>php-constants</code> preset</a>.</p><h2 id="a-function-is-undefined-after-prefixing" tabindex="-1">A function is undefined after prefixing <a class="header-anchor" href="#a-function-is-undefined-after-prefixing" aria-label="Permalink to “A function is undefined after prefixing”">​</a></h2><p>Some functions exist in PHP only on certain setups, and libraries ship a polyfill for the others. Strauss-RS leaves the common ones alone (<code>getallheaders()</code>, the <code>apache_*</code> functions and <code>fastcgi_finish_request()</code>, for example). For any other function that your own code or PHP expects to find under its original name, use <a href="./exclusions.html#one-function"><code>exclude_from_prefix.functions</code></a>.</p><p>Run <code>explain</code> with the function name to see which setting decided it.</p><h2 id="i-fixed-a-setting-and-my-source-files-still-have-the-wrong-name" tabindex="-1">I fixed a setting and my source files still have the wrong name <a class="header-anchor" href="#i-fixed-a-setting-and-my-source-files-still-have-the-wrong-name" aria-label="Permalink to “I fixed a setting and my source files still have the wrong name”">​</a></h2><p>If <code>update_call_sites</code> already rewrote your files, the old name is gone from them and a new run cannot restore it. Put the files back with <code>git checkout</code>, fix the setting, and run <code>prefix</code> again. See <a href="./updating-your-code.html#it-does-not-undo-itself">updating your own code</a>.</p><h2 id="a-theme-passes-a-collection-and-my-plugin-rejects-it" tabindex="-1">A theme passes a Collection and my plugin rejects it <a class="header-anchor" href="#a-theme-passes-a-collection-and-my-plugin-rejects-it" aria-label="Permalink to “A theme passes a Collection and my plugin rejects it”">​</a></h2><p>After prefixing, <code>Illuminate\\Support\\Collection</code> in a theme and <code>Acme\\Plugin\\Vendor\\Illuminate\\Support\\Collection</code> in your plugin are two different classes. Strauss-RS cannot make them interchangeable. Where your plugin takes objects from outside, accept <code>iterable</code>, <code>Traversable</code> or <code>array</code> and wrap the value in your own prefixed class inside your code. Do the same for values you hand back.</p><p>A <code>class_alias()</code> from the original name to the prefixed class works only if nothing else has declared the original name, so it is not safe for a library that other plugins or themes might also bundle.</p><h2 id="the-summary-says-files-were-skipped-or-could-not-be-analysed" tabindex="-1">The summary says files were skipped or could not be analysed <a class="header-anchor" href="#the-summary-says-files-were-skipped-or-could-not-be-analysed" aria-label="Permalink to “The summary says files were skipped or could not be analysed”">​</a></h2><p>Files that Strauss-RS cannot read are reported on stderr. Check that the file is valid PHP. <code>sh bin/strauss-rs.sh analyse path/to/file.php</code> shows what it sees in one file.</p>`,15)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};